# The PDF Ingestor's oversight rows, 2026-10-27: commitments matched by Id read back at 13:45 and by Owner + What prefix (never an
# assumed Id), and today's and last night's mistakes, each with a mechanical mitigation. Parameterised: no text is spliced into SQL.
Add-Type -AssemblyName System.Data
$cn = New-Object System.Data.SqlClient.SqlConnection($env:KOR_ENGINEERINGTOOLS_STANDARDSDB); $cn.Open()
function Exec($sql, $params) { $c = $cn.CreateCommand(); $c.CommandText = $sql; foreach ($k in $params.Keys) { [void]$c.Parameters.AddWithValue($k, $params[$k]) }; $c.ExecuteNonQuery() }

# commitment 16: the SQL rule - done, with its evidence
"16 done: " + (Exec "UPDATE oversight.Commitment SET State = N'done', Evidence = @e, UpdatedAtUtc = SYSDATETIMEOFFSET(), ClosedAtUtc = SYSDATETIMEOFFSET() WHERE Id = 16 AND Owner = N'PDF Ingestor' AND What LIKE N'Send the loader''s acceptance rule%' AND State = N'open'" @{ "@e" = "adf6caa3 pushed (ls-remote read back 13:46:26): tools/SqlQuery/rows_the_rule_loader_refuses.sql; live 13:46:08 = 0 rows; probe VALUES refuses forty-eight/in, blank names, maybe/bool and passes 48/in, yes please/bool, a rule row - the C# test's verdicts" })
# commitment 15: the twin trace - doing (builds running)
"15 doing: " + (Exec "UPDATE oversight.Commitment SET State = N'doing', UpdatedAtUtc = SYSDATETIMEOFFSET() WHERE Id = 15 AND Owner = N'PDF Ingestor' AND What LIKE N'Trace 10-26%' AND State = N'open'" @{})

$m = "INSERT INTO oversight.Mistake (OccurredLocal, Session, What, Cost, ClassCode, SurfaceCode, CaughtBy, Mitigation, MitigationKind, MitigationRef, MitigationOwner, State, RecordedBy) VALUES (@o, N'PDF Ingestor', @w, @c, N'claim-without-artifact', NULL, @by, @mit, @kind, @ref, @owner, @st, N'PDF Ingestor')"
$hook = "a PreToolUse hook on SendMessage that refuses a message carrying an HH:MM time, or a run id or commit hash, unless the same string appears in a tool output of the last 3 steps (the clock rule and the hash rule made mechanical; the existing stop hook does this for absence claims in replies, not for peer messages)"
"m1: " + (Exec $m @{ "@o" = "2026-10-27 00:12-04:12"; "@w" = "Wrote clock times to operations-ee without reading them, four times in one night: gate start 00:12 (clock 00:11), 02:19 (02:12), 04:12 (03:40), 03:52 (not read). Each corrected in a follow-up message once read."; "@c" = "four correction messages; ee planning on wrong times"; "@by" = "self"; "@mit" = $hook; "@kind" = "hook"; "@ref" = "Claude Code settings (Ian's to change)"; "@owner" = "Ian"; "@st" = "owed" })
"m2: " + (Exec $m @{ "@o" = "2026-10-27 10:32"; "@w" = "Wrote 'clock read 10:34' to operations-ee without reading the clock (date said 10:32:54) - the same class again, the morning after recording it."; "@c" = "one correction message"; "@by" = "self"; "@mit" = $hook; "@kind" = "hook"; "@ref" = "Claude Code settings (Ian's to change)"; "@owner" = "Ian"; "@st" = "owed" })
"m3: " + (Exec $m @{ "@o" = "2026-10-27 03:40"; "@w" = "Wrote the step-185 gate's run id as '58cf...' to operations-ee without reading it; the run was 8acd14bc."; "@c" = "one correction message"; "@by" = "self"; "@mit" = $hook; "@kind" = "hook"; "@ref" = "Claude Code settings (Ian's to change)"; "@owner" = "Ian"; "@st" = "owed" })
"m4: " + (Exec $m @{ "@o" = "2026-10-27 04:10"; "@w" = "Recorded '40112 S2.03: we read none of its steel' (step-185 doc, ee, Ian's summary) from a render of our model, without opening the DXF; the next morning's look found 3,085 BEAM polylines read - the beams ARE read, only no model writes beams."; "@c" = "item (1) scoped as a reader fix for a morning; corrected in the 46cc2d78 message"; "@by" = "self"; "@mit" = "a reader-side claim ('not read', 'reads none') names the DXF file and the layer count it was checked against, as a 'Checked:' line - the reply stop hook already demands it; extend it to docs/pdf-intake/*.md writes"; "@kind" = "hook"; "@ref" = "tools/claude_* guard (Ian's settings)"; "@owner" = "Ian"; "@st" = "owed" })
"m5: " + (Exec $m @{ "@o" = "2026-10-27 06:50"; "@w" = "Told operations-ee the suite had '3 known' failures at the midpoint; there were 4 known (TheSameDrawingsShiftedOnThePage fails late). Counted from memory, not from the record."; "@c" = "one correction in the final report"; "@by" = "self"; "@mit" = "the known-failure list is a file (scratchpad is not allowed: a test trait or a list in the repo) and every suite report diffs the run's failures against it, printing new / known / fixed"; "@kind" = "code"; "@ref" = "owed: PDF Ingestor"; "@owner" = "PDF Ingestor"; "@st" = "owed" })
"m6: " + (Exec $m @{ "@o" = "2026-10-27 02:53"; "@w" = "Drafted migration 124's header with 'nothing seen between 100 and 530 sq ft' while the first pass had listed 213, 395 and 464-465; caught re-reading before sending to ee."; "@c" = "none: caught before it left"; "@by" = "self"; "@mit" = "an absence claim inside a migration header carries the query that proves it (the prior-art guard covers db/*.sql creation, not its prose)"; "@kind" = "rule"; "@ref" = "KOR.Drafter db headers"; "@owner" = "PDF Ingestor"; "@st" = "owed" })
$cn.Close()
